#include<iostream>
using namespace std;
class MonHoc{
	private:
		int ma;
		string ten;
		int soTin;
	public:
		void nhap(){
			cout<<"Nhap ma: ";
			cin>>ma;
			cout<<"Nhap ten: ";
			cin.ignore();
			getline(cin, ten);
			cout<<"Nhap so tin chi: ";
			cin>>soTin;
		}
		void xuat(){
			cout<<endl<<ma<<" "<<ten<<" "<<soTin;
		}
		int getTin(){
			return soTin;
		}
};
class QL{
	private:
		int maKy;
		int soMon;
		MonHoc *mh;
	public:
		QL(){
			maKy = 0;
			soMon = 0;
			mh = new MonHoc[soMon];
		}
		void nhap(){
			cout<<"Nhap ma ky: ";
			cin>>maKy;
			cout<<"Nhap so mon: ";
			cin>>soMon;
			mh = new MonHoc[soMon];
			for(int i=0; i<soMon; i++){
				mh[i].nhap();
			}
		}
		void xuat(){
			cout<<maKy<<" "<<soMon;
			for(int i=0; i<soMon; i++){
				mh[i].xuat();
			}
		}
		int tongTin(){
			int tong = 0;
			for(int i=0; i<soMon; i++){
				tong += mh[i].getTin();
			}
		}
		~QL(){
			delete []mh;
		}
};
int main(){
	int n;
	cout<<"Nhap so ky hoc: ";
	cin>>n;
	QL *ql = new QL[n];
	for(int i=0; i<n; i++){
		ql[i].nhap();
	}
	for(int i=0; i<n; i++){
		ql[i].xuat();
	}
	for(int i=0; i<n; i++){
		cout<<"Tong tin ky la: "<<ql[i].tongTin();
	}
}

